/* Broadway set additions — cards appended after stage.js.
   (stage.js exceeds the push size limit, so remaining cards live here instead of being
   edited into it. Must stay directly after 'stage.js' in sets/manifest.js.) */
(function () {
  var S = window.CardSets && window.CardSets.get('stage');
  if (!S) return;
  var extra = [{"name":"Majestic Theatre","rarity":"legendary","id":"majestic-theatre","subtitle":"Theatre","details":"Opened in 1927, this grand musical house on 44th Street hosted The Phantom of the Opera for 35 years, a record-setting Broadway residency.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1b/Majestic_Theatre_-_NYC_%2852302522949%29.jpg/500px-Majestic_Theatre_-_NYC_%2852302522949%29.jpg"},{"name":"Palace Theatre","rarity":"legendary","id":"palace-theatre","subtitle":"Theatre","details":"Opened in 1913, the Palace on Broadway was vaudeville's ultimate booking; top billing there was a performer's badge of arrival.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/09/Palace_Theatre_%28New_York_City%29_%2854076031977%29.jpg/500px-Palace_Theatre_%28New_York_City%29_%2854076031977%29.jpg"},{"name":"New Amsterdam Theatre","rarity":"legendary","id":"new-amsterdam-theatre","subtitle":"Theatre","details":"A Beaux-Arts landmark opened in 1903 and former home of the Ziegfeld Follies, restored by Disney for The Lion King's 1997 premiere.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/27/New_Amsterdam_Theater_-_Aladdin_%2848193454637%29.jpg/500px-New_Amsterdam_Theater_-_Aladdin_%2848193454637%29.jpg"},{"name":"Gershwin Theatre","rarity":"epic","id":"gershwin-theatre","subtitle":"Theatre","details":"Opened in 1973, Broadway's largest house at 1,933 seats, and the theatre where the musical Wicked first opened in 2003.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c4/Gershwin2022.jpg/500px-Gershwin2022.jpg"},{"name":"Winter Garden Theatre","rarity":"epic","id":"winter-garden-theatre","subtitle":"Theatre","details":"Opened in 1911 on Broadway itself, one of only three houses with that address claim, and home to Cats for 18 years.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/39/Winter_Garden_Theatre_Nov_2021_01.jpg/500px-Winter_Garden_Theatre_Nov_2021_01.jpg"},{"name":"St. James Theatre","rarity":"epic","id":"st-james-theatre","subtitle":"Theatre","details":"Opened in 1927 on 44th Street, a landmark musical house whose stage hosted landmark productions including Oklahoma! and The Producers.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cc/StJamesTheatre070922.jpg/500px-StJamesTheatre070922.jpg"},{"name":"Shubert Theatre","rarity":"epic","id":"shubert-theatre","subtitle":"Theatre","details":"Opened in 1913 on Shubert Alley as the Shubert organization's flagship, it housed A Chorus Line for that musical's 15-year run.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/12/Shubert_Theatre_June_2026_4.jpg/500px-Shubert_Theatre_June_2026_4.jpg"},{"name":"Ziegfeld Theatre","rarity":"epic","id":"ziegfeld-theatre","subtitle":"Theatre","details":"Florenz Ziegfeld's lavish 1927 showplace for his Follies stood until 1966, when it was demolished to make way for an office tower.","image":"https://upload.wikimedia.org/wikipedia/commons/1/18/Ziegfeld-Theatre-1931.jpg"},{"name":"Richard Rodgers Theatre","rarity":"rare","id":"richard-rodgers-theatre","subtitle":"Theatre","details":"Opened in 1925 on 46th Street and renamed for composer Richard Rodgers in 1990, the theatre where Hamilton opened in 2015.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c6/Rodgers_Theater_-_Hamilton_%2848193460677%29.jpg/500px-Rodgers_Theater_-_Hamilton_%2848193460677%29.jpg"},{"name":"Minskoff Theatre","rarity":"rare","id":"minskoff-theatre","subtitle":"Theatre","details":"Opened in 1973 a floor above Times Square, this large musical house received The Lion King in its 2006 transfer from the New Amsterdam.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/08/Minskoff_Theatre_NYC_2007.jpg/500px-Minskoff_Theatre_NYC_2007.jpg"},{"name":"Imperial Theatre","rarity":"rare","id":"imperial-theatre","subtitle":"Theatre","details":"A Shubert house opened in 1923 and designed with musicals in mind, it gave Les Misérables a long Broadway home after its 1990 transfer.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6a/Imperial_Theater_-_ain%27t_too_proud_%2848193459947%29.jpg/500px-Imperial_Theater_-_ain%27t_too_proud_%2848193459947%29.jpg"},{"name":"Neil Simon Theatre","rarity":"rare","id":"neil-simon-theatre","subtitle":"Theatre","details":"Opened in 1927 as the Alvin, this 46th Street house was renamed in 1983 to honor playwright Neil Simon during his lifetime.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/28/Neil_Simon_Theatre_%2848269598196%29.jpg/500px-Neil_Simon_Theatre_%2848269598196%29.jpg"},{"name":"Eugene O'Neill Theatre","rarity":"rare","id":"eugene-o-neill-theatre","subtitle":"Theatre","details":"Opened in 1925, this intimate 49th Street playhouse staged successes from Spring Awakening to The Book of Mormon.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/47/Eugene_O%27Neill_Theatre_-_Book_of_Mormon_%2848295951286%29.jpg/500px-Eugene_O%27Neill_Theatre_-_Book_of_Mormon_%2848295951286%29.jpg"},{"name":"August Wilson Theatre","rarity":"rare","id":"august-wilson-theatre","subtitle":"Theatre","details":"Opened in 1925 as the Guild Theatre, it was renamed in 2005 for playwright August Wilson, a first such honor for a Black artist.","image":"https://upload.wikimedia.org/wikipedia/commons/f/f3/Augustwilsontheatre.jpg"},{"name":"Hippodrome Theatre","rarity":"rare","id":"hippodrome-theatre","subtitle":"Theatre","details":"Broadway's lost giant: a 1905 spectacle palace seating 5,300, famed for pageants large enough to include live elephants.","image":"https://upload.wikimedia.org/wikipedia/commons/4/4c/Hippodrome_NYC_c1905_crop.jpg"},{"name":"Lyric Theatre","rarity":"uncommon","id":"lyric-theatre","subtitle":"Theatre","details":"Opened in 1998 on 43rd Street from the remains of two earlier theatres, it later staged the two-part Harry Potter and the Cursed Child.","image":"https://images.ctfassets.net/1aemqu6a6t65/1naaun0MdbCTFAb9Knoc31/07b9b0977b75f8a5325c195db22e6936/Harry-Potter-and-the-Cursed-Child-Broadway-Manhattan-NYC-Photo-AKA-NYC-2.jpg?w=1200&h=800&q=75"},{"name":"Music Box Theatre","rarity":"uncommon","id":"music-box-theatre","subtitle":"Theatre","details":"Composer Irving Berlin helped create this intimate 1921 playhouse on 45th Street, later home to Dear Evan Hansen's long Broadway run.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/41/Music_Box_Theater_-_Front_%2848193460267%29.jpg/500px-Music_Box_Theater_-_Front_%2848193460267%29.jpg"},{"name":"Studio 54","rarity":"uncommon","id":"studio-54","subtitle":"Theatre","details":"Opened as a theatre in 1927, later famed as a disco, the 54th Street venue returned to legit use with Roundabout productions including Cabaret.","image":"assets/sets/compress/stage-additions__studio-54.webp"},{"name":"Broadway Theatre","rarity":"uncommon","id":"broadway-theatre","subtitle":"Theatre","details":"Opened in 1924 and one of only three houses fronting on Broadway itself, this large theatre hosted major musicals and prizefights alike.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0d/King_Kong_at_the_Broadway_Theater_%2848047447453%29.jpg/500px-King_Kong_at_the_Broadway_Theater_%2848047447453%29.jpg"},{"name":"Lunt-Fontanne Theatre","rarity":"uncommon","id":"lunt-fontanne-theatre","subtitle":"Theatre","details":"Opened in 1910 on 46th Street and named for acting couple Alfred Lunt and Lynn Fontanne, married stars synonymous with Broadway elegance.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/09/Lunt-Fontanne_Theatre_-_Dave_Chappelle_%2848296060697%29.jpg/500px-Lunt-Fontanne_Theatre_-_Dave_Chappelle_%2848296060697%29.jpg"},{"name":"Longacre Theatre","rarity":"uncommon","id":"longacre-theatre","subtitle":"Theatre","details":"Opened in 1913 on 48th Street, its name preserved Longacre Square, the earlier name for the crossroads that became Times Square.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5f/The_Longacre_Theatre_-_The_Prom_%2848193461707%29.jpg/500px-The_Longacre_Theatre_-_The_Prom_%2848193461707%29.jpg"},{"name":"Belasco Theatre","rarity":"uncommon","id":"belasco-theatre","subtitle":"Theatre","details":"Producer David Belasco opened this 44th Street house in 1907, filling it with Tiffany lamps and a balcony long said to be haunted.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b4/Belasco_Theatre_%2852302749285%29.jpg/500px-Belasco_Theatre_%2852302749285%29.jpg"},{"name":"Walter Kerr Theatre","rarity":"uncommon","id":"walter-kerr-theatre","subtitle":"Theatre","details":"Opened in 1921 as the Ritz on 48th Street and later renamed for critic Walter Kerr, it hosted the concert residency Springsteen on Broadway.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/61/Walter_Kerr_Theatre_-_Hadestown_%2848295952136%29.jpg/500px-Walter_Kerr_Theatre_-_Hadestown_%2848295952136%29.jpg"},{"name":"Vivian Beaumont Theater","rarity":"uncommon","id":"vivian-beaumont-theater","subtitle":"Theatre","details":"Opened at Lincoln Center in 1965, the only Broadway house outside the Theatre District, and named for philanthropist Vivian Beaumont.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/be/My_Fair_Lady_at_the_Lincoln_Center_Theatre_%2848047493287%29.jpg/500px-My_Fair_Lady_at_the_Lincoln_Center_Theatre_%2848047493287%29.jpg"},{"name":"Hudson Theatre","rarity":"uncommon","id":"hudson-theatre","subtitle":"Theatre","details":"Opened in 1903, the oldest surviving Broadway theatre spent decades as a television studio before returning to plays and musicals in 2017.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5b/Hudson_Theatre_%2852302264678%29.jpg/500px-Hudson_Theatre_%2852302264678%29.jpg"},{"name":"Al Hirschfeld Theatre","rarity":"uncommon","id":"al-hirschfeld-theatre","subtitle":"Theatre","details":"Opened in 1924 as the Martin Beck, this 45th Street house was renamed for Al Hirschfeld, caricaturist whose drawings defined Broadway faces.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/64/Al_Hirschfeld_Theatre_-_Moulin_Rouge_%2848296061427%29.jpg/500px-Al_Hirschfeld_Theatre_-_Moulin_Rouge_%2848296061427%29.jpg"},{"name":"Lyceum Theatre","rarity":"uncommon","id":"lyceum-theatre","subtitle":"Theatre","details":"Opened in 1903 on 45th Street, the Lyceum holds the distinction of being Broadway's oldest continually operating legitimate theatre.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/ff/Lyceum_Theatre_%2848295950156%29.jpg/500px-Lyceum_Theatre_%2848295950156%29.jpg"},{"name":"Morosco Theatre","rarity":"uncommon","id":"morosco-theatre","subtitle":"Theatre","details":"From 1917 to 1982 this 45th Street house premiered Death of a Salesman and Cat on a Hot Tin Roof before demolition despite public protests.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b0/Morosco_Theatre%2C_New_York_City%2C_at_night.jpg/500px-Morosco_Theatre%2C_New_York_City%2C_at_night.jpg"},{"name":"Mark Hellinger Theatre","rarity":"uncommon","id":"mark-hellinger-theatre","subtitle":"Theatre","details":"Opened in 1930 on 51st Street and remembered as My Fair Lady's original home, the building survived after its stage life as a church.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8e/Times-square-church.jpg/500px-Times-square-church.jpg"},{"name":"Barrymore Theatre","rarity":"common","id":"barrymore-theatre","subtitle":"Theatre","details":"Actress Ethel Barrymore opened this 47th Street theatre in 1928 with The Kingdom of God, the house bearing her family name.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/17/Barrymore_Theatre_%2852302264853%29.jpg/1280px-Barrymore_Theatre_%2852302264853%29.jpg"},{"name":"Bernard B. Jacobs Theatre","rarity":"common","id":"bernard-b-jacobs-theatre","subtitle":"Theatre","details":"Opened in 1927 as the Royale on 45th Street, it was renamed in 2005 to honor Bernard B. Jacobs, longtime president of the Shubert Organization.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a0/Jacobs_Theater_-_The_Ferryman_%2848193412316%29.jpg/1280px-Jacobs_Theater_-_The_Ferryman_%2848193412316%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},{"name":"Booth Theatre","rarity":"common","id":"booth-theatre","subtitle":"Theatre","details":"Opened in 1913 beside the Shubert, this intimate 45th Street house honored Edwin Booth, America's great 19th-century tragedian.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/00/Booth_Theatre_%2848295953591%29.jpg/500px-Booth_Theatre_%2848295953591%29.jpg"},{"name":"Broadhurst Theatre","rarity":"common","id":"broadhurst-theatre","subtitle":"Theatre","details":"Opened in 1917 on 44th Street and named for playwright George Broadhurst, a successful dramatist whose own hits filled Broadway stages.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/ff/Broadhurst_Theater_-_Frankie_and_Johnny_in_the_Clair_de_Lune_%2848193410426%29.jpg/1280px-Broadhurst_Theater_-_Frankie_and_Johnny_in_the_Clair_de_Lune_%2848193410426%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},{"name":"Circle in the Square Theatre","rarity":"common","id":"circle-in-the-square-theatre","subtitle":"Theatre","details":"Opened in 1972 beneath Paramount Plaza, Broadway's thrust-stage house placed audiences on three sides of the action in the round.","image":"https://upload.wikimedia.org/wikipedia/commons/d/df/Circle_In_The_Square.jpeg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled"},{"name":"Gerald Schoenfeld Theatre","rarity":"common","id":"gerald-schoenfeld-theatre","subtitle":"Theatre","details":"Opened in 1917 as the Plymouth on 45th Street, it was renamed in 2005 for Gerald Schoenfeld, chairman of the Shubert Organization.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f6/Schoenfeld_Theater_-_Come_From_Away_%2848193460457%29.jpg/500px-Schoenfeld_Theater_-_Come_From_Away_%2848193460457%29.jpg"},{"name":"Golden Theatre","rarity":"common","id":"golden-theatre","subtitle":"Theatre","details":"Opened in 1927 on 45th Street, among the smaller Shubert houses of its era, and an improbable long-term home for the puppet musical Avenue Q.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/af/John_Golden_Theatre_-_Operation_Mincemeat_%2855282653092%29.jpg/500px-John_Golden_Theatre_-_Operation_Mincemeat_%2855282653092%29.jpg"},{"name":"Hayes Theater","rarity":"common","id":"hayes-theater","subtitle":"Theatre","details":"Opened in 1912 as the Little Theatre, Broadway's smallest house at 597 seats, renamed in honor of actress Helen Hayes.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5d/Hayes_Theater_%2851495253685%29.jpg/1280px-Hayes_Theater_%2851495253685%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},{"name":"James Earl Jones Theatre","rarity":"common","id":"james-earl-jones-theatre","subtitle":"Theatre","details":"Opened in 1912 as the Cort Theatre, this 48th Street house was renamed in 2022 to honor the actor James Earl Jones.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1b/JamesEarlJonesTheatre.jpg/1280px-JamesEarlJonesTheatre.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},{"name":"Lena Horne Theatre","rarity":"common","id":"lena-horne-theatre","subtitle":"Theatre","details":"Opened in 1926 as the Mansfield and long known as the Brooks Atkinson, renamed in 2022 for Lena Horne, a first for a Black woman on Broadway.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a0/W_47_St_Nov_2022_08.jpg/1280px-W_47_St_Nov_2022_08.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},{"name":"Marquis Theatre","rarity":"common","id":"marquis-theatre","subtitle":"Theatre","details":"Opened in 1986 within the Marriott Marquis hotel, a modern large house built as part of the Times Square hotel development.","image":"https://thumb.wikimedia.org/wikipedia/en/thumb/4/4b/Marquis_Theatre_marquee_Oct_2016_day.jpeg/1280px-Marquis_Theatre_marquee_Oct_2016_day.jpeg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},{"name":"Nederlander Theatre","rarity":"common","id":"nederlander-theatre","subtitle":"Theatre","details":"Opened in 1921 on 41st Street, Broadway's southernmost house, and home to Rent throughout that musical's entire original run.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/63/Nederlander_Theatre_-_Pretty_Woman_%2848295956906%29.jpg/500px-Nederlander_Theatre_-_Pretty_Woman_%2848295956906%29.jpg"},{"name":"Samuel J. Friedman Theatre","rarity":"common","id":"samuel-j-friedman-theatre","subtitle":"Theatre","details":"Opened in 1925 as the Biltmore on 47th Street, later renamed for publicist Samuel J. Friedman and home to Manhattan Theatre Club productions.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ac/W_47_St_Nov_2021_109.jpg/500px-W_47_St_Nov_2021_109.jpg"},{"name":"Stephen Sondheim Theatre","rarity":"common","id":"stephen-sondheim-theatre","subtitle":"Theatre","details":"Opened in 1918 as Henry Miller's Theatre, renamed in 2010 for composer Stephen Sondheim while he was alive to accept the honor.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f7/Anything_Goes_at_Stephen_Sondheim_Theatre.jpg/1280px-Anything_Goes_at_Stephen_Sondheim_Theatre.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},{"name":"Todd Haimes Theatre","rarity":"common","id":"todd-haimes-theatre","subtitle":"Theatre","details":"Opened in 1918 as the Selwyn on 42nd Street, Roundabout Theatre Company's flagship house, later renamed for artistic director Todd Haimes.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a3/Todd_Haimes_Theatre_%2855283572766%29.jpg/500px-Todd_Haimes_Theatre_%2855283572766%29.jpg"},{"name":"Ambassador Theatre","rarity":"common","id":"ambassador-theatre","subtitle":"Theatre","details":"Opened in 1921 on 49th Street, this Shubert house received the long-running revival of Chicago in 2003 and kept it for decades.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e6/Ambassador_Theatre_-_Chicago_%2848296059772%29.jpg/1280px-Ambassador_Theatre_-_Chicago_%2848296059772%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},{"name":"George M. Cohan Theatre","rarity":"common","id":"george-m-cohan-theatre","subtitle":"Theatre","details":"George M. Cohan built and starred in this theatre at Broadway and 43rd Street, which welcomed audiences from 1911 until 1938.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fb/George_M._Cohan%27s_Theatre%2C_West_43rd_Street%2C_Manhattan.jpg/500px-George_M._Cohan%27s_Theatre%2C_West_43rd_Street%2C_Manhattan.jpg"},{"name":"Empire Theatre","rarity":"common","id":"empire-theatre","subtitle":"Theatre","details":"A leading stock-company house opened in 1893 at Broadway and 40th Street, demolished in 1953 after six decades of Broadway productions.","image":"https://upload.wikimedia.org/wikipedia/commons/a/a8/Empire_Theatre_41st_Street.jpg"},{"name":"Casino Theatre","rarity":"common","id":"casino-theatre","subtitle":"Theatre","details":"A Moorish-style fantasy opened in 1882 at Broadway and 39th Street, famed for roof-garden entertainments and chorus spectacles until 1930.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/87/Casino_Theatre,_Broadway_and_39th_Street,_Manhattan_-_crop.jpg/500px-Casino_Theatre,_Broadway_and_39th_Street,_Manhattan_-_crop.jpg"},{"name":"Knickerbocker Theatre","rarity":"common","id":"knickerbocker-theatre","subtitle":"Theatre","details":"Opened in 1893 at Broadway and 38th Street, this house premiered works by operetta composer Victor Herbert before closing in 1930.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e0/Knickerbocker_Theatre_1908.jpg/500px-Knickerbocker_Theatre_1908.jpg"},{"name":"Astor Theatre","rarity":"common","id":"astor-theatre","subtitle":"Theatre","details":"A Shubert flagship opened in 1906 on 45th Street, demolished in 1982 during the hotel clearances that reshaped Times Square.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/45/Astor_Theatre%2C_Broadway%2C_1936.jpg/500px-Astor_Theatre%2C_Broadway%2C_1936.jpg"},{"name":"Stephen Sondheim","rarity":"legendary","id":"stephen-sondheim","subtitle":"Creator","details":"He wrote lyrics for West Side Story and Gypsy before composing Company, Follies, Sweeney Todd and Into the Woods, reshaping the musical.","image":"assets/sets/compress/stage-additions__stephen-sondheim.webp"},{"name":"Richard Rodgers","rarity":"legendary","id":"richard-rodgers","subtitle":"Creator","details":"Composer who partnered first with Lorenz Hart, then with Hammerstein on Oklahoma!, Carousel, South Pacific, The King and I and The Sound of Music.","image":"https://www.wfmt.com/wp-content/uploads/2024/05/rodgers-169-962x541.jpg"},{"name":"Oscar Hammerstein II","rarity":"legendary","id":"oscar-hammerstein-ii","subtitle":"Creator","details":"Lyricist and librettist whose work ranged from Show Boat to The Sound of Music, and who mentored the young Stephen Sondheim.","image":"https://www.cheatsheet.com/wp-content/uploads/2020/02/Oscar-Hammerstein-II.jpg?w=787&h=1024"},{"name":"Andrew Lloyd Webber","rarity":"legendary","id":"andrew-lloyd-webber","subtitle":"Creator","details":"Composer of Cats, The Phantom of the Opera, Evita and School of Rock, and the defining architect of the blockbuster megamusical.","image":"https://bluthner.co.uk/assets/img/company/people-sir-andrew-lloyd-webber.jpg?_cchid=116f7eb28a2f9cc42ae0b0d999391cd8"},{"name":"Lin-Manuel Miranda","rarity":"epic","id":"lin-manuel-miranda","subtitle":"Creator","details":"He wrote the book, music and lyrics for In the Heights and Hamilton, and originated leading roles in both Broadway productions.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/92/Lin-Manuel_Miranda_in_Hamilton.jpg/500px-Lin-Manuel_Miranda_in_Hamilton.jpg"},{"name":"Leonard Bernstein","rarity":"epic","id":"leonard-bernstein","subtitle":"Creator","details":"Composer and conductor behind On the Town, Wonderful Town, Candide and West Side Story, written between engagements on the symphony podium.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/11/Leonard_Bernstein_by_Jack_Mitchell_%28high_quality%29.jpg/500px-Leonard_Bernstein_by_Jack_Mitchell_%28high_quality%29.jpg"},{"name":"Cole Porter","rarity":"epic","id":"cole-porter","subtitle":"Creator","details":"Songwriter of Anything Goes and Kiss Me, Kate, Cole Porter brought unmatched wit and sophistication to golden-age Broadway scores.","image":"https://upload.wikimedia.org/wikipedia/commons/4/4c/Coleporter.jpg"},{"name":"Irving Berlin","rarity":"epic","id":"irving-berlin","subtitle":"Creator","details":"Songwriter Irving Berlin gave Broadway Annie Get Your Gun and Call Me Madam while shaping a century of American popular song.","image":"https://upload.wikimedia.org/wikipedia/commons/0/05/Irving_Berlin_NYWTS.jpg"},{"name":"George Gershwin","rarity":"epic","id":"george-gershwin","subtitle":"Creator","details":"Composer of Girl Crazy, Of Thee I Sing and Porgy and Bess, George Gershwin packed a landmark Broadway career into a life ended at 38.","image":"https://upload.wikimedia.org/wikipedia/commons/7/72/Portrait_of_George_Gershwin_LCCN2004662906.jpg"},{"name":"Tennessee Williams","rarity":"epic","id":"tennessee-williams","subtitle":"Creator","details":"Playwright of The Glass Menagerie, A Streetcar Named Desire and Cat on a Hot Tin Roof, he became American drama's great Southern poet.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/78/Tennessee_Williams_NYWTS.jpg/500px-Tennessee_Williams_NYWTS.jpg"},{"name":"Eugene O'Neill","rarity":"epic","id":"eugene-o-neill","subtitle":"Creator","details":"Playwright of Long Day's Journey into Night and The Iceman Cometh, Eugene O'Neill won a Nobel Prize and remade American drama.","image":"https://upload.wikimedia.org/wikipedia/commons/3/38/ONeill-Eugene-LOC.jpg"},{"name":"John Kander","rarity":"rare","id":"john-kander","subtitle":"Creator","details":"Composer John Kander, with lyricist Fred Ebb, created the scores for Cabaret, Chicago and Kiss of the Spider Woman.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0e/JohnKander-byPhilipRomano.jpg/500px-JohnKander-byPhilipRomano.jpg"},{"name":"Stephen Schwartz","rarity":"rare","id":"stephen-schwartz","subtitle":"Creator","details":"Songwriter behind Godspell, Pippin and Wicked, three original Broadway productions that each passed 1,900 performances.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/27/StephenSchwartz-byPhilipRomano.jpg/500px-StephenSchwartz-byPhilipRomano.jpg"},{"name":"Alan Menken","rarity":"rare","id":"alan-menken","subtitle":"Creator","details":"Composer Alan Menken moved from Little Shop of Horrors to Disney's stage era with Beauty and the Beast, Newsies and Aladdin.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4a/Alan_Menken_2013_%28cropped%29.jpg/500px-Alan_Menken_2013_%28cropped%29.jpg"},{"name":"Jerry Herman","rarity":"rare","id":"jerry-herman","subtitle":"Creator","details":"Composer-lyricist Jerry Herman wrote Hello, Dolly!, Mame and La Cage aux Folles, earning a reputation as Broadway's great optimist.","image":"https://upload.wikimedia.org/wikipedia/commons/2/23/Jerry_Herman_2010.jpg"},{"name":"Arthur Miller","rarity":"rare","id":"arthur-miller","subtitle":"Creator","details":"Playwright Arthur Miller wrote Death of a Salesman, The Crucible and A View from the Bridge, defining postwar American drama.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9e/Arthur_Miller_1966.jpg/500px-Arthur_Miller_1966.jpg"},{"name":"Edward Albee","rarity":"rare","id":"edward-albee","subtitle":"Creator","details":"Playwright Edward Albee shook Broadway with Who's Afraid of Virginia Woolf?, then wrote A Delicate Balance and Three Tall Women.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/83/Edward_Albee%2C_1975.jpg/500px-Edward_Albee%2C_1975.jpg"},{"name":"August Wilson","rarity":"rare","id":"august-wilson","subtitle":"Creator","details":"Playwright August Wilson chronicled Black American life across the ten-play Century Cycle, including Fences and The Piano Lesson.","image":"https://upload.wikimedia.org/wikipedia/en/f/fa/August_wilson.jpg"},{"name":"Fred Ebb","rarity":"uncommon","id":"fred-ebb","subtitle":"Creator","details":"Lyricist Fred Ebb, the biting half of Kander and Ebb, gave Cabaret and Chicago much of their cynical sparkle and snap.","image":"https://www.theatricalrights.co.uk/wp-content/uploads/sites/4/2016/04/Fred-Ebb-crop-600x600.png"},{"name":"Tim Rice","rarity":"uncommon","id":"tim-rice","subtitle":"Creator","details":"Lyricist Tim Rice partnered on Evita and Jesus Christ Superstar, then contributed lyrics to The Lion King and Aida.","image":"https://upload.wikimedia.org/wikipedia/commons/b/b4/Tim_Rice%2C_1_December_2020.jpg"},{"name":"Marvin Hamlisch","rarity":"uncommon","id":"marvin-hamlisch","subtitle":"Creator","details":"Composer of A Chorus Line, Marvin Hamlisch joined the rare company of winners of an Emmy, Grammy, Oscar, Tony and Pulitzer Prize.","image":"https://upload.wikimedia.org/wikipedia/commons/6/62/Marvin_Hamlisch_-_1970s.jpg"},{"name":"Cy Coleman","rarity":"uncommon","id":"cy-coleman","subtitle":"Creator","details":"Composer Cy Coleman brought a jazz musician's swing to Sweet Charity, Barnum and City of Angels.","image":"https://upload.wikimedia.org/wikipedia/commons/6/68/Composer_Cy_coleman_%2832841370298%29.jpg"},{"name":"Jule Styne","rarity":"uncommon","id":"jule-styne","subtitle":"Creator","details":"Composer Jule Styne supplied the tunes for Gypsy, Funny Girl and Bells Are Ringing, cornerstones of Broadway's golden age.","image":"https://upload.wikimedia.org/wikipedia/commons/1/12/Jule_Styne_%281961_still%29.jpg"},{"name":"Frank Loesser","rarity":"uncommon","id":"frank-loesser","subtitle":"Creator","details":"Songwriter Frank Loesser created Guys and Dolls and How to Succeed in Business Without Really Trying, and published his own songs.","image":"https://upload.wikimedia.org/wikipedia/commons/7/71/Frank_Loesser_studio_photo%2C_1936.jpg"},{"name":"Frederick Loewe","rarity":"uncommon","id":"frederick-loewe","subtitle":"Creator","details":"Composer Frederick Loewe partnered with Alan Jay Lerner on Brigadoon, Paint Your Wagon, My Fair Lady and Camelot.","image":"https://upload.wikimedia.org/wikipedia/commons/4/44/Frederick_Loewe_%281962%29.jpg"},{"name":"Neil Simon","rarity":"uncommon","id":"neil-simon","subtitle":"Creator","details":"Playwright Neil Simon filled Broadway with The Odd Couple, Barefoot in the Park and his autobiographical Brighton Beach trilogy.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Neil%20Simon%201982.jpg"},{"name":"Alan Jay Lerner","rarity":"common","id":"alan-jay-lerner","subtitle":"Creator","details":"Lyricist and librettist Alan Jay Lerner shaped My Fair Lady and Camelot, and the film musical Gigi, with Frederick Loewe.","image":"https://upload.wikimedia.org/wikipedia/commons/6/66/Alan_Jay_Lerner_%281962%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled"},{"name":"Ira Gershwin","rarity":"common","id":"ira-gershwin","subtitle":"Creator","details":"Lyricist Ira Gershwin set words to brother George's music from Lady, Be Good! to Porgy and Bess, then worked with Kurt Weill and Cole Porter.","image":"https://upload.wikimedia.org/wikipedia/commons/4/45/Ira_Gershwin_1925.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled"},{"name":"David Mamet","rarity":"common","id":"david-mamet","subtitle":"Creator","details":"Playwright David Mamet forged a clipped, profane stage language in Glengarry Glen Ross, Speed-the-Plow and American Buffalo.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/00/David_Mamet_2_by_David_Shankbone.JPG/500px-David_Mamet_2_by_David_Shankbone.JPG"},{"name":"Tony Kushner","rarity":"common","id":"tony-kushner","subtitle":"Creator","details":"Playwright Tony Kushner wrote the two-part Angels in America and the musical Caroline, or Change, works of sweeping political imagination.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5c/Tony_Kushner_-_Hollywood_and_Socialism_-_The_Laura_Flanders_Show_2.png/500px-Tony_Kushner_-_Hollywood_and_Socialism_-_The_Laura_Flanders_Show_2.png"},{"name":"Ethel Merman","rarity":"legendary","id":"ethel-merman","subtitle":"Star","details":"Star of Annie Get Your Gun and Gypsy, Ethel Merman possessed a trumpet of a voice that filled Broadway houses without amplification.","image":"https://assets.playbill.com/editorial/_embeddedGallerySize/7a1cd92b5b74800e869f1d05200262d8-nypl.digitalcollections.510d47e4-6c01-a3d9-e040-e00a18064a99.001.w.jpg"},{"name":"Angela Lansbury","rarity":"legendary","id":"angela-lansbury","subtitle":"Star","details":"Angela Lansbury won five Tony Awards across four decades, from Mame to her Mrs. Lovett in Sweeney Todd.","image":"https://assets.playbill.com/editorial/_embeddedGallerySize/0032f64f07abdabd55ac0b57ff1ceed0-orig9.jpg"},{"name":"Patti LuPone","rarity":"legendary","id":"patti-lupone","subtitle":"Star","details":"Patti LuPone won Tony Awards as Eva Perón in Evita and Rose in Gypsy, and gave Company a fierce new Joanne.","image":"https://assets.playbill.com/editorial/_enhancementFullwidth/87fb67986ddae96988674aa9697a39b1-patti-lupone-as-eva-peron-singing-22dont-cry-for-me-argentina-22-in-a-scene-from-the-broadway-production-of-the-musical-22evita.jpg"},{"name":"Bernadette Peters","rarity":"legendary","id":"bernadette-peters","subtitle":"Star","details":"Bernadette Peters became Stephen Sondheim's modern muse in Sunday in the Park with George, Into the Woods and Gypsy.","image":"https://assets.playbill.com/editorial/_embeddedGallerySize/bfac35a801b8d4916b1fe4001b9a4e40-into-the-woods-broadway-production-photo-1987-bernadette-peters-hr.jpg"},{"name":"Mary Martin","rarity":"epic","id":"mary-martin","subtitle":"Star","details":"Mary Martin starred as Nellie in South Pacific, flew as Peter Pan, and played Maria in The Sound of Music.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/80/Mary_Martin_1.jpg/500px-Mary_Martin_1.jpg"},{"name":"Carol Channing","rarity":"epic","id":"carol-channing","subtitle":"Star","details":"Carol Channing played Dolly Levi in Hello, Dolly! more than 5,000 times, making the matchmaker inseparable from her own persona.","image":"https://upload.wikimedia.org/wikipedia/commons/7/79/Carol_Channing_-_1964.jpg"},{"name":"Julie Andrews","rarity":"epic","id":"julie-andrews","subtitle":"Star","details":"Julie Andrews originated Eliza Doolittle in My Fair Lady and Guenevere in Camelot on stage before her film career began.","image":"https://upload.wikimedia.org/wikipedia/commons/c/c9/Julie_Andrews_Rex_Harrison_My_Fair_Lady.JPG"},{"name":"Barbra Streisand","rarity":"epic","id":"barbra-streisand","subtitle":"Star","details":"Barbra Streisand originated Fanny Brice in Funny Girl on Broadway in 1964, after an earlier turn in I Can Get It for You Wholesale.","image":"https://clickamericana.com/wp-content/uploads/Vintage-Barbra-Streisand-Funny-Girl-via-ClickAmericana_com.jpg"},{"name":"Chita Rivera","rarity":"epic","id":"chita-rivera","subtitle":"Star","details":"Dancer Chita Rivera originated Anita in West Side Story, Velma in Chicago and the title role in Kiss of the Spider Woman.","image":"https://upload.wikimedia.org/wikipedia/commons/6/65/Chita_Rivera_1.jpg"},{"name":"Audra McDonald","rarity":"epic","id":"audra-mcdonald","subtitle":"Star","details":"Audra McDonald won six Tony Awards across all four acting categories, a record built on Carousel, Ragtime and Porgy and Bess.","image":"https://upload.wikimedia.org/wikipedia/commons/f/f9/Audra_mcdonald_2021_2.jpg"},{"name":"Zero Mostel","rarity":"rare","id":"zero-mostel","subtitle":"Star","details":"Zero Mostel originated Tevye in Fiddler on the Roof and Pseudolus in A Funny Thing Happened on the Way to the Forum.","image":"https://upload.wikimedia.org/wikipedia/commons/2/20/Zero_Mostel_-_Fiddler.JPG"},{"name":"Gwen Verdon","rarity":"rare","id":"gwen-verdon","subtitle":"Star","details":"Gwen Verdon originated Lola in Damn Yankees and Charity in Sweet Charity, becoming Bob Fosse's muse and her generation's defining dancer.","image":"https://upload.wikimedia.org/wikipedia/commons/4/42/Gwen_Verdon_1954.jpg"},{"name":"Elaine Stritch","rarity":"rare","id":"elaine-stritch","subtitle":"Star","details":"Elaine Stritch made Company's Joanne and her song 'The Ladies Who Lunch' her own, and starred in Sail Away and A Delicate Balance.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ec/Elaine_Stritch.jpg/500px-Elaine_Stritch.jpg"},{"name":"Nathan Lane","rarity":"rare","id":"nathan-lane","subtitle":"Star","details":"Nathan Lane won acclaim as Pseudolus in Forum, Max Bialystock in The Producers and Roy Cohn in Angels in America.","image":"https://upload.wikimedia.org/wikipedia/commons/a/a3/NathanLane2018_%28cropped%29.jpg"},{"name":"Sutton Foster","rarity":"rare","id":"sutton-foster","subtitle":"Star","details":"Sutton Foster rose from the chorus to originate the title role in Thoroughly Modern Millie, then led The Music Man and Anything Goes.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3a/SuttonFoster-byPhilipRomano.jpg/500px-SuttonFoster-byPhilipRomano.jpg"},{"name":"Yul Brynner","rarity":"rare","id":"yul-brynner","subtitle":"Star","details":"Yul Brynner played the King in The King and I for 4,625 performances, turning a single role into a lifetime's signature.","image":"https://upload.wikimedia.org/wikipedia/commons/0/0b/Publicity_press_photo_of_Yul_Brynner_in_1960_%28cropped%29.jpg"},{"name":"Jonathan Groff","rarity":"rare","id":"jonathan-groff","subtitle":"Star","details":"Tony winner for Merrily We Roll Along, he originated Spring Awakening's Melchior, Hamilton's King George and Just in Time's Bobby Darin.","image":"https://upload.wikimedia.org/wikipedia/commons/f/f9/Jonathan_Groff_77th_Tony_Awards_2024.jpg"},{"name":"Cynthia Erivo","rarity":"rare","id":"cynthia-erivo","subtitle":"Star","details":"Cynthia Erivo won Tony and Grammy Awards in her Broadway debut as Celie in The Color Purple, then played Elphaba in the film Wicked.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9b/Cynthia_Erivo_-_Wicked-FYC-2_%28cropped%29.jpg/500px-Cynthia_Erivo_-_Wicked-FYC-2_%28cropped%29.jpg"},{"name":"Barbara Cook","rarity":"uncommon","id":"barbara-cook","subtitle":"Star","details":"Soprano Barbara Cook originated Marian in The Music Man and Amalia in She Loves Me, setting a golden-age standard for ingénue singing.","image":"https://images.nypl.org/index.php?id=4063552&t=w"},{"name":"Idina Menzel","rarity":"uncommon","id":"idina-menzel","subtitle":"Star","details":"Idina Menzel originated Maureen in Rent and Elphaba, the green-skinned witch, in Wicked, belting both roles into Broadway history.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6a/IdinaMenzel-byPhilipRomano.jpg/500px-IdinaMenzel-byPhilipRomano.jpg"},{"name":"Ben Vereen","rarity":"uncommon","id":"ben-vereen","subtitle":"Star","details":"Ben Vereen played Judas in Jesus Christ Superstar and won a Tony as Pippin's Leading Player, carrying Bob Fosse's style in motion.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a1/Ben_Vereen_at_TIFF_2014.jpg/500px-Ben_Vereen_at_TIFF_2014.jpg"},{"name":"Joel Grey","rarity":"uncommon","id":"joel-grey","subtitle":"Star","details":"Joel Grey originated Cabaret's Emcee on stage and reprised the role on film, and played song-and-dance man George M. Cohan in George M!","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5d/JoelGrey-byPhilipRomano.jpg/500px-JoelGrey-byPhilipRomano.jpg"},{"name":"Kristin Chenoweth","rarity":"uncommon","id":"kristin-chenoweth","subtitle":"Star","details":"Kristin Chenoweth won a Tony in You're a Good Man, Charlie Brown and originated Glinda in Wicked, packing a tornado into four-foot-eleven.","image":"https://imaging.broadway.com/images/regular-43/w480/116805-18.jpg"},{"name":"Ben Platt","rarity":"uncommon","id":"ben-platt","subtitle":"Star","details":"Ben Platt originated Evan in Dear Evan Hansen and won the Tony Award for it, then earned praise as Ned in the Parade revival.","image":"https://imaging.broadway.com/images/custom/w1470/80245-13.jpg"},{"name":"Lea Michele","rarity":"uncommon","id":"lea-michele","subtitle":"Star","details":"Lea Michele originated Wendla in Spring Awakening, headlined the Funny Girl revival as Fanny, and played Florence in the 2025 Chess revival.","image":"https://media-cldnry.s-nbcnews.com/image/upload/t_fit-1120w,f_auto,q_auto:best/rockcms/2022-09/lea-michele-fanny-brice-funny-girl-mc-220907-08-6d5e3c.jpg"},{"name":"Aaron Tveit","rarity":"uncommon","id":"aaron-tveit","subtitle":"Star","details":"Aaron Tveit won a Tony as Christian in Moulin Rouge!, after originating roles in Next to Normal and Catch Me If You Can.","image":"https://broadwaydirect.com/wp-content/uploads/2023/01/01-Aaron-Tveit-as-Christian-Photo-by-Matthew-Murphy-scaled-e1673965801297.jpg"},{"name":"Leslie Odom Jr.","rarity":"uncommon","id":"leslie-odom-jr","subtitle":"Star","details":"Leslie Odom Jr. won a Tony Award as Aaron Burr in Hamilton and later headlined a Broadway revival of Purlie Victorious.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d9/Leslie_Odom_Jr._2024_%28cropped%29.jpg/500px-Leslie_Odom_Jr._2024_%28cropped%29.jpg"},{"name":"Jessie Mueller","rarity":"uncommon","id":"jessie-mueller","subtitle":"Star","details":"Jessie Mueller won a Tony playing Carole King in Beautiful and originated Jenna, the pie-making heroine of Waitress.","image":"https://www.theatermania.com/wp-content/uploads/sites/4/2023/03/149406.jpg?w=620"},{"name":"Renée Elise Goldsberry","rarity":"uncommon","id":"ren-e-elise-goldsberry","subtitle":"Star","details":"Renée Elise Goldsberry originated Angelica Schuyler in Hamilton and won a Tony Award for it, after appearing in The Color Purple.","image":"assets/sets/compress/stage-additions__ren-e-elise-goldsberry.webp"},{"name":"Gavin Creel","rarity":"uncommon","id":"gavin-creel","subtitle":"Star","details":"Gavin Creel won a Tony Award for Hello, Dolly! and starred in Thoroughly Modern Millie, Hair and Into the Woods before his death in 2024.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/17/GavinCreel.jpg/500px-GavinCreel.jpg"},{"name":"Rex Harrison","rarity":"common","id":"rex-harrison","subtitle":"Star","details":"Rex Harrison originated Henry Higgins in My Fair Lady on Broadway and guarded his signature role with legendary protectiveness.","image":"https://upload.wikimedia.org/wikipedia/commons/e/e5/Rex_Harrison_Allan_Warren.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled"},{"name":"Alfred Drake","rarity":"common","id":"alfred-drake","subtitle":"Star","details":"Alfred Drake originated Curly in Oklahoma! and later inherited the King in The King and I, defining the golden-age leading man.","image":"https://upload.wikimedia.org/wikipedia/commons/a/a7/Alfred_Drake.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled"},{"name":"John Raitt","rarity":"common","id":"john-raitt","subtitle":"Star","details":"John Raitt originated Billy Bigelow in Carousel and Sid in The Pajama Game; his daughter is singer Bonnie Raitt.","image":"https://upload.wikimedia.org/wikipedia/commons/2/29/John_Raitt_in_Oklahoma_still.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled"},{"name":"Lena Horne","rarity":"common","id":"lena-horne","subtitle":"Star","details":"Lena Horne starred in Jamaica in 1957, and her solo show The Lady and Her Music played 333 performances in 1981.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/75/Lena_Horne%2C_1946.jpg/1280px-Lena_Horne%2C_1946.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},{"name":"Pearl Bailey","rarity":"common","id":"pearl-bailey","subtitle":"Star","details":"Pearl Bailey led the all-Black production of Hello, Dolly! in 1967 and received a special Tony Award for her Dolly Levi.","image":"https://upload.wikimedia.org/wikipedia/commons/4/44/Pearl_Bailey_-_publicity.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled"},{"name":"Michael Crawford","rarity":"common","id":"michael-crawford","subtitle":"Star","details":"Michael Crawford originated the Phantom in The Phantom of the Opera in London and on Broadway, the mask molded to his face.","image":"https://upload.wikimedia.org/wikipedia/commons/c/ce/Michael_Crawford_2025_%28cropped%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled"},{"name":"Mandy Patinkin","rarity":"common","id":"mandy-patinkin","subtitle":"Star","details":"Mandy Patinkin originated Che in Evita and George in Sunday in the Park with George, singing both with ferocious intensity.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/63/MandyPatinkin.jpg/500px-MandyPatinkin.jpg"},{"name":"Hugh Jackman","rarity":"common","id":"hugh-jackman","subtitle":"Star","details":"Hugh Jackman won a Tony as Peter Allen in The Boy from Oz and later played Harold Hill in The Music Man.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d8/Hugh_Jackman_Is_This_Thing_On-68_%28cropped%29.jpg/500px-Hugh_Jackman_Is_This_Thing_On-68_%28cropped%29.jpg"},{"name":"James Earl Jones","rarity":"common","id":"james-earl-jones","subtitle":"Star","details":"James Earl Jones starred as Troy Maxson in Fences and in The Great White Hope, bringing his resonant voice live to Broadway.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3c/James_Earl_Jones_Baltimore.jpg/1280px-James_Earl_Jones_Baltimore.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"},{"name":"Phillipa Soo","rarity":"common","id":"phillipa-soo","subtitle":"Star","details":"Phillipa Soo originated Eliza Hamilton in Hamilton, then starred in the stage productions of Amélie and Camelot.","image":"https://www.theatermania.com/wp-content/uploads/sites/4/2023/03/117643.jpg?w=620"},{"name":"Jeremy Jordan","rarity":"common","id":"jeremy-jordan","subtitle":"Star","details":"Jeremy Jordan originated Jack Kelly in Newsies and later stepped into the role of Bobby Darin in Just in Time.","image":"https://www.hypnoweb.net/photo/2/1517/ok/1-serieserie.jpg"},{"name":"Alex Newell","rarity":"common","id":"alex-newell","subtitle":"Star","details":"Alex Newell won a Tony Award playing Lulu in Shucked, a supporting performance built around a once-in-a-generation voice.","image":"assets/sets/compress/stage-additions__alex-newell.webp"},{"name":"Daniel Radcliffe","rarity":"common","id":"daniel-radcliffe","subtitle":"Star","details":"Daniel Radcliffe starred in Equus and How to Succeed on Broadway before winning a Tony for Merrily We Roll Along.","image":"https://images.ctfassets.net/6pezt69ih962/6mEoIpgRoeg4V5acBLJiop/c4d383b3c080f1e6678c0a4f95686b32/Daniel_Radcliffe__Jonathan_Groff_and_Lindsay_Mendez_in_MERRILY_WE_ROLL_ALONG_at_New_York_Theatre_Workshop__Photo_by_Joan_Mar.jpg"},{"name":"Eva Noblezada","rarity":"common","id":"eva-noblezada","subtitle":"Star","details":"Eva Noblezada played Kim in Miss Saigon at seventeen and originated Eurydice in Hadestown, earning two Tony nominations in her twenties.","image":"https://assets.playbill.com/editorial/_embeddedGallerySize/cbade0238e36bd2ee507818ac11b4d74-hadestown-london-national-theatre-production-photo-2018-1.%20Eva%20Noblezada%20(Eurydice)%20in%20Hadestown%20at%20National%20Theatre%20(c)%20Helen%20Maybanks_HR.jpg"},{"name":"Memory","rarity":"legendary","id":"memory","subtitle":"Song","details":"From Cats, this is ageing glamour cat Grizabella's plea to be accepted back, sung near the end of Andrew Lloyd Webber's long-running musical.","image":"https://i0.wp.com/seligfilmnews.com/wp-content/uploads/2019/09/Keri-Ren%C3%A9-Fuller-as-Grizabella-in-the-North-American-Tour-of-CATS.-Photo-by-Matthew-Murphy-2019.jpg?fit=696%2C464&ssl=1"},{"name":"Defying Gravity","rarity":"legendary","id":"defying-gravity","subtitle":"Song","details":"From Wicked, Elphaba sings this Act One finale as she rejects the Wizard's rule and rises above Oz on her broom for the first time.","image":"https://images.squarespace-cdn.com/content/v1/6355f1d801c557236d4b3e06/05655cf5-290f-459b-adb1-ebe99f5c4be0/Sheridan+Adams+Defying+Gravity+WICKED+%28c%29+Jeff+Busby.jpg?format=500w"},{"name":"The Music of the Night","rarity":"legendary","id":"the-music-of-the-night","subtitle":"Song","details":"From The Phantom of the Opera, the Phantom sings this aria to Christine in his underground lair beneath the Paris opera house.","image":"https://imaging.broadway.com/images/regular-43/w800/87529-22.jpg"},{"name":"One Day More","rarity":"epic","id":"one-day-more","subtitle":"Song","details":"From Les Misérables, this Act One finale weaves Valjean, Javert, Cosette, Marius and the students together on the eve of the barricades.","image":"assets/sets/compress/stage-additions__one-day-more.webp"},{"name":"Alexander Hamilton","rarity":"epic","id":"alexander-hamilton","subtitle":"Song","details":"From Hamilton, the opening number has the full company narrate the orphan immigrant's arrival and rise toward the American Revolution.","image":"https://cdn.concreteplayground.com/content/uploads/2019/03/Hamiliton-Broadway-JoanMarcus.jpg?webp=false"},{"name":"All That Jazz","rarity":"epic","id":"all-that-jazz","subtitle":"Song","details":"From Chicago, Velma Kelly leads this brassy opening number that establishes the musical's world of jazz clubs, fame and murder trials.","image":"https://cloudimages.broadwayworld.com/upload12/1817606/tn-500_josefinagabrielle(velmakelly)inchicago.credittristramkenton.jpg?format=auto&width=1400"},{"name":"Seasons of Love","rarity":"epic","id":"seasons-of-love","subtitle":"Song","details":"From Rent, the whole company sings this ensemble anthem about measuring a year by the love in it, placed at the top of the second act.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9a/Cast_of_Rent_performing_%22Seasons_of_Love%22_at_Broadway_on_Broadway%2C_2005.jpg/500px-Cast_of_Rent_performing_%22Seasons_of_Love%22_at_Broadway_on_Broadway%2C_2005.jpg"},{"name":"I Dreamed a Dream","rarity":"rare","id":"i-dreamed-a-dream","subtitle":"Song","details":"From Les Misérables, Fantine sings this lament after losing her factory job and selling what she had left to support her daughter Cosette.","image":"assets/sets/compress/stage-additions__i-dreamed-a-dream.webp"},{"name":"Send in the Clowns","rarity":"rare","id":"send-in-the-clowns","subtitle":"Song","details":"From A Little Night Music, Desirée sings Stephen Sondheim's reflective ballad, which became the most widely recorded song of his career.","image":"https://www.melodymunitz.com/uploads/1/3/7/6/137605083/a-little-night-music-101_1.jpg"},{"name":"If I Were a Rich Man","rarity":"rare","id":"if-i-were-a-rich-man","subtitle":"Song","details":"From Fiddler on the Roof, milkman Tevye sings this comic daydream about wealth and respect while working in his barn in Anatevka.","image":"https://www.nsmt.org/uploads/1/9/9/5/19956447/nsmt-fiddler-24-tevye-richman-pl-thumb_orig.jpg"},{"name":"Tonight","rarity":"rare","id":"tonight","subtitle":"Song","details":"From West Side Story, Tony and Maria sing this duet on her fire escape, echoed by rival gangs and Anita as the city moves toward a rumble.","image":"assets/sets/compress/stage-additions__tonight.webp"},{"name":"Everything's Coming Up Roses","rarity":"rare","id":"everything-s-coming-up-roses","subtitle":"Song","details":"From Gypsy, Mama Rose sings this forceful Act One closer after June leaves, vowing to make Louise a star instead, whatever it takes.","image":"https://broadwaydirect.com/wp-content/uploads/2024/12/Audra-McDonald-in-GYPSY-Photo-by-Julieta-Cervantes-1024x683.jpg"},{"name":"Don't Cry for Me Argentina","rarity":"rare","id":"don-t-cry-for-me-argentina","subtitle":"Song","details":"From Evita, Eva Perón sings this address to a vast crowd from the Casa Rosada balcony after becoming Argentina's First Lady.","image":"https://www.sassymamasg.com/wp-content/uploads/2018/03/evita-dont-cry-for-me-argentina-balcony.jpg"},{"name":"One","rarity":"rare","id":"one","subtitle":"Song","details":"From A Chorus Line, the full cast performs this gold-clad finale in perfect unison, celebrating the anonymous dancers of the chorus line.","image":"assets/sets/compress/stage-additions__one.webp"},{"name":"And I Am Telling You I'm Not Going","rarity":"rare","id":"and-i-am-telling-you-i-m-not-going","subtitle":"Song","details":"From Dreamgirls, Effie White sings this defiant Act One showstopper as she refuses to accept being pushed out of the group and her love's life.","image":"https://seatplan.com/cdn/images/c/production/Dreamgirls-4-700wx457h-1516034912-w960.webp"},{"name":"Circle of Life","rarity":"rare","id":"circle-of-life","subtitle":"Song","details":"From The Lion King, Rafiki and the ensemble open the musical with this sunrise ceremony presenting the newborn Simba at Pride Rock.","image":"https://cdn-imgix.headout.com/media/images/a9a34ba51ec2e6b97cbf54fd12a26b27-4.jpg?auto=compress&fm=pjpg&w=1000&h=624&crop=faces&fit=min"},{"name":"Tomorrow","rarity":"rare","id":"tomorrow","subtitle":"Song","details":"From Annie, the orphan Annie sings this signature song of optimism to comfort herself and, later in the show, President Roosevelt's cabinet.","image":"https://www.shubert.com/assets/img/Annie_Slideshow.04-5d827b1d10.jpg"},{"name":"Being Alive","rarity":"uncommon","id":"being-alive","subtitle":"Song","details":"From Company, bachelor Bobby sings this closing number after finally recognising that he wants a real connection rather than watching couples.","image":"assets/sets/compress/stage-additions__being-alive.webp"},{"name":"Some Enchanted Evening","rarity":"uncommon","id":"some-enchanted-evening","subtitle":"Song","details":"From South Pacific, French planter Emile de Becque sings this romantic standard about first seeing nurse Nellie Forbush across a crowded room.","image":"https://img.theatreroyal.co.uk/uploads/2022/07/SOUTH-PACIFIC.-Gina-Beck-Ensign-Nellie-Forbush-and-Julian-Ovenden-Emile-de-Becque.-Photo-by-Johan-Persson-scaled.jpg?resize=1584%2C990&gravity"},{"name":"The Impossible Dream","rarity":"uncommon","id":"the-impossible-dream","subtitle":"Song","details":"From Man of La Mancha, Don Quixote sings his credo to Aldonza from a prison setting framed by Cervantes awaiting the Inquisition.","image":"https://cloudimages2.broadwayworld.com/upload11/1693883/tn-500_7034copy.jpg?format=auto&width=1400"},{"name":"Let It Go","rarity":"uncommon","id":"let-it-go","subtitle":"Song","details":"From Frozen, Elsa sings this solo as she builds her ice palace in isolation; written for the 2013 film and carried into the stage musical.","image":"https://images.ctfassets.net/6pezt69ih962/urvWa1KYgzfGKgXQUEUh1/447d483b76d0e083c7c0391600151804/frozen_header.jpg?h=825&fm=webp&q=70"},{"name":"A Whole New World","rarity":"uncommon","id":"a-whole-new-world","subtitle":"Song","details":"From Aladdin, Aladdin and Jasmine sing this duet during their magic-carpet flight; written for the film and retained for the stage version.","image":"https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEjh8N9_dUX2MECIlqvv-n7LKstf7a0kr9lvkHe57zyEF6BW2fO20BKfQf6Mpa1BVQRYA8UiAn34KxlRdasOS8VAfEO7FHJQ9dDOVKobRByz7PxKNog6FXVgbec6BWNhAN0o8dMQRODxDaz1/s640/%2528Flying+Carpet%2529+Graeme+Isaako+as+Aladdin+with+Shubshri+Kandiah+as+Jasmine+-+James+Green.jpg"},{"name":"Aquarius","rarity":"uncommon","id":"aquarius","subtitle":"Song","details":"From Hair, the Tribe opens the musical with this ensemble number announcing a new astrological age of peace, harmony and understanding.","image":"https://storage.googleapis.com/stateless-ceoblognation-com/2024/05/04f89b47-1.-amanda-lee-dionne-jordan-dobson-claude-and-the-cast-of-hair-at-signature-theatre.-photo-by-daniel-radar-.jpg"},{"name":"Luck Be a Lady","rarity":"uncommon","id":"luck-be-a-lady","subtitle":"Song","details":"From Guys and Dolls, gambler Sky Masterson sings this urgent number while rolling dice on whether he can win the bet that decides his romance.","image":"assets/sets/compress/stage-additions__luck-be-a-lady.webp"},{"name":"No One Is Alone","rarity":"common","id":"no-one-is-alone","subtitle":"Song","details":"From Into the Woods, Cinderella, the Baker, Little Red Riding Hood and Jack sing this late duet of comfort after loss deep in the woods.","image":"https://imaging.broadway.com/images/social/w630/123407-11.jpg"},{"name":"Sunday","rarity":"common","id":"sunday","subtitle":"Song","details":"From Sunday in the Park with George, Georges Seurat and the company close Act One as his famous pointillist painting assembles on stage.","image":"https://imaging.broadway.com/images/custom/w544/88113-11.jpg"},{"name":"Be Our Guest","rarity":"common","id":"be-our-guest","subtitle":"Song","details":"From Beauty and the Beast, Lumière leads the enchanted household objects in a lavish production number serving dinner to Belle.","image":"assets/sets/compress/stage-additions__be-our-guest.webp"},{"name":"Dancing Queen","rarity":"common","id":"dancing-queen","subtitle":"Song","details":"From Mamma Mia!, ABBA's hit anchors a joyful ensemble sequence and returns in the finale, sung by Donna with Sophie and her friends.","image":"https://media-cldnry.s-nbcnews.com/image/upload/t_fit_1500w/rockcms/2025-10/mamma-mia-lm-251006-main-1-69d051.jpg"},{"name":"You Can't Stop the Beat","rarity":"common","id":"you-can-t-stop-the-beat","subtitle":"Song","details":"From Hairspray, Tracy Turnblad leads the exuberant finale as the television dance show's cast is integrated on air in 1962 Baltimore.","image":"https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEhCtqOh_gBkxfrz7ZjtLLGEBLWRPVZ1Z3VflApab10v2_jcI_svC2zSf2u6zapp0Q5LBw0dQwfNk1j5xqkCX7dtTYnupBxnZWu6lAFy9tCR4bwSB-dTKY3KpOCaiKbVYXff28c-vTCqJdm3m9oMyYkLYUwlnvURcZ_27XrpzmFOyN-FjxLT90r0CzfPMw/w1200-h630-p-k-no-nu/HAIRSPRAY-You-Cant-Stop-The-Beat.-Photo-by-Chris-Bennion-and-Jeremy-Daniel.-1024x701.jpg"},{"name":"Springtime for Hitler","rarity":"common","id":"springtime-for-hitler","subtitle":"Song","details":"From The Producers, this is the deliberately outrageous title number of the flop Max Bialystock stages inside the musical, played entirely for farce.","image":"https://cloudimages2.broadwayworld.com/upload12/1929266/tn-500_theproducersproductionphoto10.jpg?format=auto&width=1400"},{"name":"I Believe","rarity":"common","id":"i-believe","subtitle":"Song","details":"From The Book of Mormon, Elder Price sings this earnest solo listing his beliefs after his mission in Uganda tests everything he was taught.","image":"https://images.leedsheritagetheatres.com/uploads/2025/08/BOMProductionPortrait-1.jpg?fit=900%2C900"},{"name":"Waving Through a Window","rarity":"common","id":"waving-through-a-window","subtitle":"Song","details":"From Dear Evan Hansen, Evan Hansen sings this opening solo about feeling invisible at school and longing to be noticed by anyone at all.","image":"https://assets.playbill.com/editorial/_facebookOpenGraph/20ad2dd9e1ffc9822d7eb1c41205d9cf-dearevanhansen-benplatt-hr.jpg"},{"name":"Wait for Me","rarity":"common","id":"wait-for-me","subtitle":"Song","details":"From Hadestown, Orpheus sings this determined number as he sets out on the road to the underworld to bring Eurydice back to the living.","image":"https://images.ctfassets.net/6pezt69ih962/4uWdI68gEHxgBH15nr9qjS/ef6b2ed43b451ddda8ee6396bd7cd73f/1._HADESTOWN_-_Original_Broadway_Company__Photography_by_Matthew_Murphy_.jpg?h=618&fm=webp&q=70"},{"name":"She Used to Be Mine","rarity":"common","id":"she-used-to-be-mine","subtitle":"Song","details":"From Waitress, pie-baker Jenna sings this reflective solo about the person she was before an unhappy marriage and an unexpected pregnancy.","image":"assets/sets/compress/stage-additions__she-used-to-be-mine.webp"},{"name":"Falling Slowly","rarity":"common","id":"falling-slowly","subtitle":"Song","details":"From Once, Guy and Girl first connect over this duet at a piano in a Dublin music shop; the song won the Academy Award for the original film.","image":"https://bomag.o0bc.com/wp-content/uploads/sites/2/2015/11/once-768x512.jpg"},{"name":"96,000","rarity":"common","id":"96-000","subtitle":"Song","details":"From In the Heights, Usnavi and the Washington Heights neighbours sing this ensemble fantasy about what each would do with a lottery jackpot.","image":"https://assets.playbill.com/editorial/_embeddedGallerySize/26d00602c6d884b7e9c769f2d829e864-in-the-heights-kennedy-center-production-photo-2018-96000-photo-by-teresa-wood-hr.jpg"},{"name":"I Could Have Danced All Night","rarity":"common","id":"i-could-have-danced-all-night","subtitle":"Song","details":"From My Fair Lady, Eliza Doolittle sings this joyful solo in her bedroom after triumphing at the ball in Professor Higgins' experiment.","image":"https://images.nypl.org/index.php?id=5041844&t=w"},{"name":"My Favorite Things","rarity":"common","id":"my-favorite-things","subtitle":"Song","details":"From The Sound of Music, Maria shares this cheerful catalogue of comforts early in the musical, a signature song for Rodgers and Hammerstein.","image":"https://nwamotherlode.com/wp-content/uploads/2018/04/The-Sound-of-Music-Jill-Christine-Wiley-as-Maria-Rainer-and-the-von-Trapp-children.-Photo-by-Matthew-Murphy-2_preview.jpeg"},{"name":"Willkommen","rarity":"common","id":"willkommen","subtitle":"Song","details":"From Cabaret, the Emcee opens the musical with this multilingual welcome, inviting the audience into Berlin's seedy Kit Kat Club.","image":"https://broadwaydirect.com/wp-content/uploads/2024/04/4-CABARET-Eddie-Redmayne-center-as-the-Emcee-and-the-Kit-Kat-Girls-in-CABARET-at-the-Kit-Kat-Club-at-the-August-Wilson-Theatre.-Photo-by-Marc-Brenner-1024x683.jpg"},{"name":"Summer Nights","rarity":"common","id":"summer-nights","subtitle":"Song","details":"From Grease, Danny and Sandy separately recount their summer romance to the T-Birds and Pink Ladies, in two very different versions of events.","image":"assets/sets/compress/stage-additions__summer-nights.webp"}];
  extra.forEach(function (x) {
    if (S.byId.has(x.id)) return;
    var c = { id: x.id, num: S.cards.length + 1, name: x.name, rarity: x.rarity,
              subtitle: x.subtitle, details: x.details, image: x.image, logo: '' };
    S.cards.push(c);
    S.byId.set(c.id, c);
    if (S.pools[c.rarity]) S.pools[c.rarity].push(c);
  });
})();
